////
/// Embla Slider Default Styles.
/// This needs to be imported highter up the chain than any pattern that uses it, so that the pattern can override these styles if needed.
/// https://www.embla-carousel.com/
/// Default basic styles for Embla Carousel will display a basic horizontal slider, single slide per view.
/// Customisation is should be done in a separate pattern file, using pattern related class names.  See profile-slider.scss for example.
/// To increase number of slides per view, set --slide-size CSS variable to a percentage value, e.g. 50% for 2 slides, 33.3333% for 3 slides etc.
////

:root {
    //TODO move to a more appropriate place.
    @each $name, $value in $breakpoints {
        --breakpoint-#{$name}: #{$value};
    }
}

.embla {
    margin: auto;
    max-width: 100%;
    position: relative;
    margin-top: $content-element-margin;
    // Default values
    --slide-spacing: 1.5rem;
    --slide-size: 100%;

    // Values currently being used
    --slide-spacing-current: var(--slide-spacing);
    --slide-size-current: var(--slide-size);

    //Button sizes
    --slide-btn-height: #{$measure--small3};
    --slide-btn-width: #{$measure--small3};
}

.embla__viewport {
    overflow: hidden;
}

.embla__container {
    display: flex;
    touch-action: pan-y pinch-zoom;
    margin-left: calc(var(--slide-spacing-current) * -1);
    //If ul remove inherit styles from main li styles
    margin-top: 0;
    list-style: none;
    max-width: none;
}
.embla__slide {
    transform: translate3d(0, 0, 0);
    flex: 0 0 var(--slide-size-current);
    min-width: 0;
    padding-left: var(--slide-spacing-current);
    opacity: 0.5;
    transition: opacity 600ms ease-out, transform 600ms ease-out;

    //If li remove inherit styles from main li styles
    margin-top: 0;
}

/*EMBLA DOTS*/
.embla__dots {
    padding: $measure--half 0;
    display: flex;
    justify-content: center;
    gap: $measure--half;
}

.embla__dot {
    width: $measure--half;
    height: $measure--half;
    padding: 0;
    border: 0;
    border-radius: $border-radius-round;
    background-color: $color-gray5;
    cursor: pointer;
    transition: width 0.15s ease;
    &--selected {
        width: $measure--small4;

        background-color: $color-nearblack;
    }
}
//Cascade values, so for example if no desktop value it'll value back to the tablet if that's set.
$embla-slide-size-fallback: var(--slide-size);
$embla-slide-spacing-fallback: var(--slide-spacing);

@each $name, $value in $breakpoints {
    $embla-slide-size-fallback: var(
        --slide-size-#{$name},
        #{$embla-slide-size-fallback}
    );

    $embla-slide-spacing-fallback: var(
        --slide-spacing-#{$name},
        #{$embla-slide-spacing-fallback}
    );

    @media (min-width: $value) {
        .embla {
            --slide-size-current: #{$embla-slide-size-fallback};
            --slide-spacing-current: #{$embla-slide-spacing-fallback};
        }
    }
}

.embla__slide--is-in-view,
.embla__slide--is-snapped {
    opacity: 1;
    transform: none;
    transition: opacity 600ms ease-out, transform 600ms ease-out;
}
.embla__heading {
    padding-right: calc(
        (#{$measure--small3} * 2) + (#{$measure--half} * 2)
    ); //Avoid heading overlapping btns. Value calcualted on btn width * 2 + btns gap value * 2 to allow for additional space
}
.embla__btns {
    margin-bottom: $content-element-margin;
    display: flex;
    justify-content: flex-end;
    gap: $measure--half;
    .embla__heading + .embla & {
        position: absolute;
        top: calc((var(--slide-btn-height) + #{$measure--half}) * -1);
        right: 0;
    }
}
.embla__btn {
    position: relative;
    border-radius: 50%;
    background: $color-purewhite;
    border: $border-width-hairline solid $color-nearblack;
    color: $color-nearblack;
    width: var(--slide-btn-width);
    height: var(--slide-btn-height);
    display: flex;
    justify-content: center;
    align-items: center;
    &:active {
        outline: 2px dotted $color-nearblack;
        outline-offset: 3px;
    }
    &:focus {
        z-index: 1;
        outline: 3px solid $color-nearblack;
        outline-offset: 3px;
    }

    &[disabled] {
        opacity: 0.5;
    }
}

//Remove styling from slider if disabled at that viewport
@each $name, $value in $breakpoints {
    @media (min-width: $value) {
        .embla[data-disable-from='#{$name}'] {
            .embla__viewport {
                overflow: visible;
            }

            .embla__container {
                display: grid;
                grid-template-columns: repeat(
                    var(--inactive-columns, 3),
                    minmax(0, 1fr)
                );
                gap: var(--slide-spacing-current);
                margin-left: 0;
                touch-action: auto;
            }

            .embla__slide {
                flex: none;
                padding-left: 0;
                opacity: 1;
                transform: none;
            }
            .embla__btns,
            .embla__dots {
                display: none;
            }
        }
    }
}
