@mixin tabs-links-style() {
    .tabs__links {
        align-items: stretch;
        bottom: 0rem;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: inherit;
        list-style-type: none;
        margin-bottom: 0;
        margin-left: 0;
        margin-top: $measure--basic;
        max-width: unset;
        overflow: visible;
        position: relative;
    }

    .tabs__links li:not([hidden]) {
        margin-bottom: 0;
        margin-top: 0;
        max-width: unset;
        text-align: center;
        margin-right: $measure--threequarters;
        display: flex;
        align-items: flex-end;
        flex: 1;
    }

    .tabs__links li:last-of-type {
        margin-right: 0;
    }

    .tabs__links li button {
        @include anchor-span();
        @include anchor-reset();
        background-image: none;
        border: $border-width-hairline $border-style-solid $color-nearblack;
        color: $color-nearblack;
        display: block;
        overflow: hidden;
        padding: 0;
        position: relative;
        transition: none;
        width: 100%;

        > span {
            @include h6style();
            font-weight: $font-weight-normal;
            align-items: flex-end;
            border-bottom-color: transparent;
            border-bottom-style: $border-style-solid;
            display: flex;
            height: 100%;
            line-height: $line-height-ratio--body;
            margin-top: 0;
            padding: $measure--half;
            justify-content: center;

            @include media('>between') {
                padding-left: $measure--threequarters;
                padding-right: $measure--threequarters;
            }
        }

        &[aria-selected='true'] {
            background: $color-red50;
            color: $color-purewhite;
            border-color: $color-red50;

            > span {
                color: $color-purewhite;
            }
        }

        &:hover {
            @include media('hover') {
                border: $border-width-hairline $border-style-solid
                    $color-nearblack;
                background: $color-gray1;
            }
        }

        &:focus,
        &:active {
            background: $color-red50;
            color: $color-purewhite;
            border: $border-width-hairline $border-style-solid $color-red50;
            outline-width: $border-width-thick;
            outline-style: $border-style-solid;
            outline-color: $color-nearblack;
            outline-offset: $border-width-thick;

            span {
                outline: none;
            }
        }
    }
}

.tabs-v26 {
    .tabs__links li {
        &:only-child {
            display: none;
        }
    }
}

// Tabs with compact width
.js .tabs-v26[data-width='compact'] .tabs__links li {
    flex: initial;
}

@include media('print') {
    .js .tabs-v26 > .tabs__links,
    .js .tabs--accordion > .accordion-v26 {
        display: none;
    }

    .js .tabs-v26 .tabs__panel[hidden] {
        display: block;
    }
}

@include media('screen') {
    .js .tabs-v26 {
        @include tabs-links-style();
    }

    .js .tabs-v26 .tabs__panel {
        padding: $measure--threequarters $measure--half $measure--half
            $measure--half;

        &:focus {
            @include outline-properties($color-nearblack);
            outline-offset: 0;
        }
    }

    .js .tabs-v26 .tabs__panel__content {
        padding: $measure--small4 0;
        @include media('<tablet') {
            padding-bottom: $measure--basic;
        }
    }

    .js .tabs-v26 .tabs__panel__heading {
        margin-top: 0;
    }
}

@include media('screen', '<=tablet') {
    .js .tabs--accordion > .accordion-v26 {
        display: block;

        .accordion__heading {
            button {
                &:hover {
                    @include media('hover') {
                        // [PLACEHOLDER]
                    }
                }
            }
        }
    }

    //
    // Nested accordion inside accordion
    //

    .js .tabs--accordion > .accordion-v26 .accordion-v26 {
        .accordion__heading {
            button {
                .accordion__heading__text,
                .accordion__heading__indicator {
                    background: transparent;
                    color: $color-linkblue;
                }
            }
            &[data-open='false'] {
                border-bottom-color: $color-gray2;
                border-bottom-style: $border-style-solid;
                border-bottom-width: $border-width-hairline;
            }
        }
    }

    // Nested tab inside tab that switches to accordion
    .js .tabs--accordion .tabs--accordion > .accordion-v26 .accordion__heading {
        &[data-open='true'] {
            button {
                .accordion__heading__indicator,
                .accordion__heading__text {
                    // [PLACEHOLDER]
                }
            }
        }
        &[data-open='false'] {
            button {
                .accordion__heading__text {
                    color: $color-gray10;
                }
            }
        }
    }

    .js .tabs--accordion > .tabs-v26 {
        display: none;
    }
}

@include media('screen', '>tablet') {
    .js .tabs--accordion > .accordion-v26 {
        display: none;
    }

    .js .tabs--accordion > .tabs-v26 {
        display: block;
    }

    .js .tabs--accordion > .tabs-v26 .accordion--nested {
        @include media('>tablet') {
            display: block;
        }
    }
}

//Style specific to UG course v26 module select input
.module-year-select__wrapper {
    display: flex;
    @include media('>tablet') {
        flex-direction: row;
        align-items: center;
        column-gap: 1rem;

        .course-v26__module-year-select {
            width: clamp(40%, 15rem, 20rem);
        }
    }

    @include media('<=tablet') {
        flex-direction: column;
        row-gap: $measure--basic;
    }
}

.key-info__module-year-select__wrapper {
    margin-top: $measure--threequarters;
    label {
        @include sr-only();
    }
}
